<?php
declare(strict_types=1);

$root=dirname(__DIR__); $lock=$root.'/storage/installed.lock'; $errors=[]; $done=false;
if (is_file($lock)) { http_response_code(403); exit('El instalador está bloqueado.'); }

foreach (['storage','storage/backups','storage/logs','storage/updates','uploads'] as $directory) {
 $path=$root.'/'.$directory;
 if(!is_dir($path) && !mkdir($path,0755,true) && !is_dir($path))$errors[]='No se pudo crear la carpeta '.$directory.'.';
}

function h(string $v): string { return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function cpanelCall(string $url,string $user,string $token,string $module,string $function,array $params): array {
 $endpoint=rtrim($url,'/').'/execute/'.$module.'/'.$function.'?'.http_build_query($params);
 $ch=curl_init($endpoint); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: cpanel '.$user.':'.$token],CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_TIMEOUT=>25]);
 $raw=curl_exec($ch); if($raw===false)throw new RuntimeException('No se pudo conectar con la API de cPanel: '.curl_error($ch)); $status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE); curl_close($ch);
 $data=json_decode($raw,true); if($status>=400||empty($data['status']))throw new RuntimeException($data['errors'][0]??'cPanel rechazó la operación.'); return $data;
}
function phpConfig(array $cfg): string { return "<?php\nreturn ".var_export($cfg,true).";\n"; }

$checks=[
 'PHP 8.1 o superior'=>version_compare(PHP_VERSION,'8.1.0','>='), 'PDO MySQL'=>extension_loaded('pdo_mysql'), 'JSON'=>extension_loaded('json'), 'mbstring'=>extension_loaded('mbstring'), 'OpenSSL'=>extension_loaded('openssl'), 'ZIP'=>extension_loaded('zip'), 'cURL (API cPanel)'=>extension_loaded('curl'), 'config escribible'=>is_writable($root.'/config'), 'storage escribible'=>is_writable($root.'/storage'), 'uploads escribible'=>is_writable($root.'/uploads')
