   $cpUrl=trim($_POST['cpanel_url']??''); $cpUser=trim($_POST['cpanel_user']??''); $cpToken=(string)($_POST['cpanel_token']??''); $dbSuffix=preg_replace('/[^a-zA-Z0-9_]/','',$_POST['db_suffix']??'arandugo'); $userSuffix=preg_replace('/[^a-zA-Z0-9_]/','',$_POST['db_user_suffix']??'arandugo');
   cpanelCall($cpUrl,$cpUser,$cpToken,'Mysql','create_database',['name'=>$dbSuffix]); cpanelCall($cpUrl,$cpUser,$cpToken,'Mysql','create_user',['name'=>$userSuffix,'password'=>$dbPass]); cpanelCall($cpUrl,$cpUser,$cpToken,'Mysql','set_privileges_on_database',['user'=>$userSuffix,'database'=>$dbSuffix,'privileges'=>'ALL PRIVILEGES']);
   $dbName=$cpUser.'_'.$dbSuffix; $dbUser=$cpUser.'_'.$userSuffix;
  }
  if($dbName===''||$dbUser===''||$dbPass==='')throw new RuntimeException('Completá los datos de la base de datos.');
  $pdo=new PDO("mysql:host={$dbHost};port=3306;dbname={$dbName};charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
  $occupied=$pdo->query("SHOW TABLES LIKE ".$pdo->quote($prefix.'%'))->fetchColumn();if($occupied!==false)throw new RuntimeException('El prefijo ya está ocupado. Elegí un prefijo exclusivo para esta instalación.');
  $schema=str_replace('{{prefix}}',$prefix,file_get_contents($root.'/database/schema.sql')); $pdo->exec($schema);
  $site=require $root.'/database/'.(!empty($_POST['demo_content'])?'demo-accountant.php':'default-site.php');
  if(empty($_POST['demo_content'])){ $site['business']=['name'=>trim($_POST['business_name']??'Mi negocio'),'category'=>'','slogan'=>'','description'=>'','email'=>'','address'=>'','hours'=>'','mapsUrl'=>'','mapsEmbedUrl'=>''];$site['header']['nameText']=$site['business']['name'];$site['header']['logo']='';$site['hero']=array_replace($site['hero'],['title'=>'','text'=>'','image'=>'']);$site['about']=array_replace($site['about'],['title'=>'','text'=>'','showInMenu'=>false]);$site['phones']=[];$site['services']=[];$site['gallery']=[];$site['gallerySettings']=['title'=>'','introHtml'=>''];$site['socials']=array_fill_keys(array_keys($site['socials']??[]),'');foreach($site['freeSections']??[] as $i=>$section)$site['freeSections'][$i]=array_replace($section,['title'=>'','menuLabel'=>'','publicLabel'=>'','showInMenu'=>false,'html'=>'','media'=>[],'ctaLabel'=>'','ctaUrl'=>'']);foreach($site['modules']??[] as $i=>$module)if(!in_array($module['key']??'',['hero','contact'],true))$site['modules'][$i]['active']=false;$site['demo']=['active'=>false,'progress'=>[]]; }
  $json=json_encode($site,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); $stmt=$pdo->prepare("INSERT INTO `{$prefix}site_profiles` (id,draft_json,published_json,published_at) VALUES (1,?,?,NOW()) ON DUPLICATE KEY UPDATE draft_json=VALUES(draft_json),published_json=VALUES(published_json)"); $stmt->execute([$json,$json]);
  $name=trim($_POST['admin_name']??'Administrador'); $username=trim($_POST['admin_user']??'admin'); $email=filter_var($_POST['admin_email']??'',FILTER_VALIDATE_EMAIL); $password=(string)($_POST['admin_password']??'');
  if(!$email||strlen($password)<10)throw new RuntimeException('El administrador necesita un correo válido y una contraseña de al menos 10 caracteres.');
  $stmt=$pdo->prepare("INSERT INTO `{$prefix}users` (name,username,email,password_hash,role) VALUES (?,?,?,?, 'admin')"); $stmt->execute([$name,$username,$email,password_hash($password,PASSWORD_DEFAULT)]);
  $baseUrl=rtrim(trim($_POST['app_url']??''),'/'); if(!filter_var($baseUrl,FILTER_VALIDATE_URL))throw new RuntimeException('La URL del sitio no es válida.');
  $config=['app'=>['name'=>'Arandu Go','url'=>$baseUrl,'timezone'=>$_POST['timezone']??'America/Asuncion','debug'=>false,'key'=>bin2hex(random_bytes(32)),'version'=>'2.2.1'],'database'=>['host'=>$dbHost,'port'=>3306,'name'=>$dbName,'user'=>$dbUser,'password'=>$dbPass,'charset'=>'utf8mb4','prefix'=>$prefix],'mail'=>['transport'=>$_POST['mail_transport']??'mail','from_email'=>trim($_POST['from_email']??$email),'from_name'=>trim($_POST['from_name']??'Arandu Go'),'sendmail_path'=>trim($_POST['sendmail_path']??'/usr/sbin/sendmail -bs'),'smtp'=>['host'=>trim($_POST['smtp_host']??''),'port'=>(int)($_POST['smtp_port']??587),'security'=>$_POST['smtp_security']??'tls','username'=>trim($_POST['smtp_user']??''),'password'=>(string)($_POST['smtp_password']??'')]],'recaptcha'=>['secret_key'=>(string)($_POST['recaptcha_secret']??'')]];
  if(file_put_contents($root.'/config/config.php',phpConfig($config),LOCK_EX)===false)throw new RuntimeException('No se pudo crear config/config.php.'); chmod($root.'/config/config.php',0600);
  file_put_contents($lock,date(DATE_ATOM)."\n",LOCK_EX); $done=true;
 }catch(Throwable $e){$errors[]=$e->getMessage();}
}
$https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https';$scriptDir=str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/install/index.php'));$basePath=preg_replace('#/install$#','',$scriptDir);$suggestedUrl=($https?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').($basePath==='/'?'':$basePath);
